/* Strict display rule for hidden attribute */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #14101e;
  --color-panel: #27203b;
  --color-border: #000000;
  --color-accent: #ffcc00;
  --color-text: #ffffff;
  --color-text-dim: #c5b8e0;
  --color-button: #4b3d6b;
  --color-button-hover: #63528c;
  --color-button-active: #33274e;
  --color-correct: #38b764;
  --color-wrong: #e03838;
  --font-family: 'Courier New', Courier, monospace, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
  background-image:
    radial-gradient(#201830 15%, transparent 16%),
    radial-gradient(#201830 15%, transparent 16%);
  background-size: 16px 16px;
  background-position: 0 0, 8px 8px;
}

.quiz-wrapper {
  width: 100%;
  max-width: 580px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* Pixel Panel styling */
.pixel-panel {
  background-color: var(--color-panel);
  border: 4px solid var(--color-border);
  box-shadow:
    inset -4px -4px 0px 0px #181326,
    inset 4px 4px 0px 0px #3f345e,
    4px 4px 0px 0px #000000;
  padding: 20px;
}

.quiz-header {
  display: flex;
  flex-direction: column;
  gap: 12px;
  text-align: center;
}

.pixel-title {
  font-size: 1.75rem;
  letter-spacing: 2px;
  color: var(--color-accent);
  text-shadow: 2px 2px #000000;
  font-weight: 900;
}

.status-bar {
  display: flex;
  justify-content: space-around;
  gap: 12px;
}

.stat-box {
  background: #191427;
  padding: 8px 16px;
  border: 2px solid var(--color-border);
  box-shadow: inset 2px 2px 0 #0f0c18;
  display: flex;
  align-items: center;
  gap: 8px;
}

.stat-label {
  font-size: 0.9rem;
  font-weight: bold;
  color: var(--color-text-dim);
}

.stat-value {
  font-size: 1.25rem;
  font-weight: bold;
  color: var(--color-accent);
}

.card {
  display: flex;
  flex-direction: column;
  gap: 18px;
  text-align: center;
}

.screen-title {
  font-size: 1.35rem;
  color: var(--color-accent);
  text-shadow: 1px 1px #000000;
}

.description {
  color: var(--color-text-dim);
  font-size: 1rem;
  line-height: 1.6;
}

.question-meta {
  text-align: left;
}

.badge {
  display: inline-block;
  background: #191427;
  color: var(--color-accent);
  padding: 4px 10px;
  font-size: 0.85rem;
  font-weight: bold;
  border: 2px solid var(--color-border);
}

.question-title {
  font-size: 1.2rem;
  text-align: left;
  min-height: 50px;
  display: flex;
  align-items: center;
  color: var(--color-text);
  outline: none;
}

.answers-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

@media (min-width: 480px) {
  .answers-grid {
    grid-template-columns: 1fr 1fr;
  }
}

/* Pixel button interactive states */
.pixel-btn,
.answer-btn {
  appearance: none;
  background-color: var(--color-button);
  color: var(--color-text);
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 12px 16px;
  border: 3px solid var(--color-border);
  box-shadow:
    inset -3px -3px 0 0 #281f3d,
    inset 3px 3px 0 0 #6e5b98,
    3px 3px 0 0 #000000;
  cursor: pointer;
  text-align: center;
  user-select: none;
  transition: none;
  word-break: break-word;
}

.pixel-btn:hover,
.answer-btn:hover:not(:disabled) {
  background-color: var(--color-button-hover);
}

.pixel-btn:focus-visible,
.answer-btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.pixel-btn:active,
.answer-btn:active:not(:disabled) {
  box-shadow:
    inset 3px 3px 0 0 #181226,
    1px 1px 0 0 #000000;
  transform: translate(2px, 2px);
  background-color: var(--color-button-active);
}

.answer-btn:disabled {
  cursor: not-allowed;
  opacity: 0.85;
}

.answer-btn.correct {
  background-color: var(--color-correct) !important;
  color: #000000 !important;
  box-shadow: inset -3px -3px 0 0 #22703d, inset 3px 3px 0 0 #6ee897, 3px 3px 0 0 #000000;
}

.answer-btn.wrong {
  background-color: var(--color-wrong) !important;
  color: #ffffff !important;
  box-shadow: inset -3px -3px 0 0 #8b2020, inset 3px 3px 0 0 #ff7575, 3px 3px 0 0 #000000;
}

.feedback-box {
  padding: 10px;
  font-weight: bold;
  border: 2px solid var(--color-border);
  background-color: #191427;
}

.feedback-box.correct {
  color: var(--color-correct);
}

.feedback-box.wrong {
  color: var(--color-wrong);
}

.result-text {
  font-size: 1.2rem;
  font-weight: bold;
  color: var(--color-text);
}

.result-details {
  color: var(--color-text-dim);
  font-size: 1rem;
}

(function () {
  'use strict';

  // 5 built-in questions with four choices each
  const QUESTIONS = [
    {
      question: 'Which element is used to define an internal stylesheet in HTML?',
      answers: ['<script>', '<style>', '<css>', '<link>'],
      correct: 1
    },
    {
      question: 'Which CSS property defines the space between cells in a grid?',
      answers: ['gap', 'spacing', 'grid-margin', 'cell-padding'],
      correct: 0
    },
    {
      question: 'In JavaScript, which method cancels a timer set with setInterval()?',
      answers: ['clearTimer()', 'stopInterval()', 'clearInterval()', 'resetInterval()'],
      correct: 2
    },
    {
      question: 'What is the standard screen width used for small mobile breakpoints?',
      answers: ['120px', '240px', '360px', '720px'],
      correct: 2
    },
    {
      question: 'Which attribute ensures screen readers immediately announce updates?',
      answers: ['aria-live="assertive"', 'aria-hidden="true"', 'role="presentation"', 'aria-readonly="true"'],
      correct: 0
    }
  ];

  const TOTAL_TIME = 60;
  const POINTS_PER_QUESTION = 100;

  // DOM references
  const startScreen = document.getElementById('start-screen');
  const quizScreen = document.getElementById('quiz-screen');
  const gameOverScreen = document.getElementById('game-over-screen');

  const startBtn = document.getElementById('start-btn');
  const restartBtn = document.getElementById('restart-btn');

  const timerEl = document.getElementById('timer');
  const liveScoreEl = document.getElementById('live-score');
  const questionNumberEl = document.getElementById('question-number');
  const questionTextEl = document.getElementById('question-text');
  const answersContainer = document.getElementById('answers-container');
  const feedbackMsg = document.getElementById('feedback-msg');

  const finalScoreEl = document.getElementById('final-score');
  const resultTitleEl = document.getElementById('result-title');
  const resultDetailsEl = document.getElementById('result-details');

  // Quiz state
  let currentQuestionIndex = 0;
  let score = 0;
  let timeLeft = TOTAL_TIME;
  let timerId = null;
  let acceptingAnswers = false;

  function updateLiveScore(val) {
    score = val;
    liveScoreEl.textContent = String(score);
  }

  function updateTimerDisplay() {
    timerEl.textContent = timeLeft + 's';
  }

  function startTimer() {
    timeLeft = TOTAL_TIME;
    updateTimerDisplay();
    clearInterval(timerId);
    timerId = setInterval(function () {
      timeLeft--;
      updateTimerDisplay();
      if (timeLeft <= 0) {
        endQuiz('Time\'s Up!');
      }
    }, 1000);
  }

  function startQuiz() {
    updateLiveScore(0);
    currentQuestionIndex = 0;
    startScreen.hidden = true;
    gameOverScreen.hidden = true;
    quizScreen.hidden = false;
    feedbackMsg.hidden = true;
    feedbackMsg.textContent = '';
    startTimer();
    renderQuestion();
  }

  function renderQuestion() {
    if (currentQuestionIndex >= QUESTIONS.length) {
      endQuiz('Quiz Complete!');
      return;
    }

    acceptingAnswers = true;
    const q = QUESTIONS[currentQuestionIndex];
    questionNumberEl.textContent = 'QUESTION ' + (currentQuestionIndex + 1) + '/' + QUESTIONS.length;
    questionTextEl.textContent = q.question;
    questionTextEl.focus();

    feedbackMsg.hidden = true;
    feedbackMsg.textContent = '';
    feedbackMsg.className = 'feedback-box';
    answersContainer.innerHTML = '';

    q.answers.forEach(function (text, index) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'answer-btn';
      btn.textContent = (index + 1) + '. ' + text;
      btn.setAttribute('aria-label', 'Option ' + (index + 1) + ': ' + text);
      btn.addEventListener('click', function () {
        if (!acceptingAnswers) return;
        handleAnswer(index, btn);
      });
      answersContainer.appendChild(btn);
    });
  }

  function handleAnswer(selectedIndex, selectedBtn) {
    acceptingAnswers = false;
    const q = QUESTIONS[currentQuestionIndex];
    const allButtons = answersContainer.querySelectorAll('.answer-btn');
    allButtons.forEach(function (btn) {
      btn.disabled = true;
    });

    if (selectedIndex === q.correct) {
      selectedBtn.classList.add('correct');
      updateLiveScore(score + POINTS_PER_QUESTION);
      feedbackMsg.textContent = '+100 CORRECT!';
      feedbackMsg.className = 'feedback-box correct';
    } else {
      selectedBtn.classList.add('wrong');
      allButtons[q.correct].classList.add('correct');
      feedbackMsg.textContent = 'INCORRECT!';
      feedbackMsg.className = 'feedback-box wrong';
    }
    feedbackMsg.hidden = false;

    setTimeout(function () {
      if (timeLeft > 0 && !quizScreen.hidden) {
        currentQuestionIndex++;
        renderQuestion();
      }
    }, 900);
  }

  function endQuiz(title) {
    clearInterval(timerId);
    acceptingAnswers = false;
    quizScreen.hidden = true;
    startScreen.hidden = true;
    gameOverScreen.hidden = false;

    resultTitleEl.textContent = title;
    finalScoreEl.textContent = score;
    const maxScore = QUESTIONS.length * POINTS_PER_QUESTION;
    const answeredCount = Math.min(currentQuestionIndex + (timeLeft > 0 ? 0 : 1), QUESTIONS.length);
    resultDetailsEl.textContent = 'You completed ' + currentQuestionIndex + ' of ' + QUESTIONS.length + ' questions with ' + timeLeft + 's remaining.';
    restartBtn.focus();
  }

  startBtn.addEventListener('click', startQuiz);
  restartBtn.addEventListener('click', startQuiz);
})();
